package run.ikaros.music;
import java.util.UUID; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.RequestHeader; import org.springframework.web.bind.annotation.RequestMapping; import org.springframework.web.bind.annotation.RequestParam; import org.springframework.web.bind.annotation.RestController; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/music/duplicates") public class MusicDuplicateController { private final MusicDuplicateService service; public MusicDuplicateController(MusicDuplicateService service){this.service=service;} @GetMapping public Mono<java.util.List<MusicDuplicateView>> find(@RequestHeader("X-Ikaros-Actor-Id") UUID ownerId,@RequestParam UUID attachmentId){return service.find(ownerId,attachmentId);} }
